      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n11/5) 5단계 팬티형 기저귀(일반라인) 주로 사용중인 9-16kg 자녀와 어머니 동반 인터뷰 모집(기저귀 착용 테스트 조사)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.19. 11:13\n조회 26\n구독\n11/5) 5단계 팬티형 기저귀(일반라인) 주로 사용중인 9-16kg 자녀와 어머니 동반 인터뷰 모집(기저귀 착용 테스트 조사)\n신청하신분은 재신청 안하셔도 됩니다\n★모모래빗★ 5단계 팬티형 기저귀(일반라인) 주사용자가 필요합니다.\n모모래빗 에코씽씽 팬티\n모모래빗 에코드라이 팬티\n모모래빗 에코컴포트핏 팬티\n모모래빗 에코드라이 썸머 팬티 & 모모래빗 5단계 팬티형 기저귀(일반라인) 주사용자가 필요합니다.\n(** 킨도의 겨우 기저귀 겉포장 아래에 작은 글씨로 풀네임이 있으며, 프리미엄이라고 안직힌 것이 일반라인 제품입니다)\n5단계 팬티형 기저귀(일반라인) 주로 사용중인 9-16kg 자녀와 어머니 동반 인터뷰 모집(기저귀 착용 테스트 조사)\n1. 일정\n11월 5일(목) 11시 ~15시 (4시간)\n11월 5일(목) 12시~16시 (4시간)\n11월 5일(목) 13시~17시 (4시간)\n** 현재 주사용 브랜드 : 하기스, 팸퍼스, 모모래빗, 페넬로페, 킨도 (일반라인 제품)\n(현 주사용 제품은 사전에 사진으로 확인합니다)\n**자녀 동반 인터뷰 *청담역 근처 키즈카페*에서 진행됩니다\n2. 조사 방법\n▶ 조사 전전날&전날 : 2개의 테스트 기저귀를 1일씩 착용해보면서 모바일 설문 작성(5분내외) <제품 택배발송 예정>\n▶ 조사 당일 : 테스트 기저귀를 착용한 상태로 도착해서 진행 중간마다 다른 기저귀로 교체 테스트를 하면서 인터뷰 진행 (기저귀 교체하는 과정을 촬영할 예정)\n자녀가 키즈 카페에서 놀다가 기저귀를 교체하는 방식으로 해당 상황을 촬영하고 인터뷰를 진행합니다.\n이는 기저귀를 착용하는 방식, 착용 전후의 전반적 상태 등을 알아보기 위함입니다.\n** 대상자 선정통화(15-20분) → 최종인터뷰 참석확정연락 → 기저귀 테스트제품 사전착용 및 모바일설문 작성 → 자녀 동반 인터뷰 최종참석\n3. 비용\n최종 인터뷰까지 참여한 경우만 : 230,000원 지급\n(참여 이후 본인 계좌이체 예정이며 기타소득신고를 위한 개인정보 입력이 필수입니다)\n4. (신청양식)\n1. 성함:\n2. 연락처:\n3. 거주지(구/동 까지):\n4. 직업(회사/부서명 등)\n5. 엄마연령(생년월일):\n6. 자녀연령(생년월일):\n7. 자녀성별(남아/여아):\n8. 자녀의 체중(kg)과 키(cm)를 모두 적어주세요.\n9. 자녀가 현재 사용하는 기저귀 크기 및 단계는? <5단계(특대형(extra Large) 팬티형 사용자 대상>\n10. 하루 평균 몇 개의 기저귀를 어머님께서 직접 교체해주시나요? <5개 이상만 가능>\n11. 자녀가 하루 평균 어린이집/유치원에 다니는 시간은? <등원하지 않는 경우 '해당없음' 가능>\nex) 9시~13시(반일반), 10시-16시(반일반), 9시~18시(종일반) 등\n12. 자녀가 지금까지 사용한 기저귀로 인한 피부 트러블/발진/불편함 이슈를 겪은 적이 있나요? <NO만 가능>\n13. 하기스, 팸퍼스, 모모래빗, 페넬로페, 킨도 중에 향후 절대 구매하고 싶지않은 기저귀 브랜드가 있다면 적어주세요. <없음도 가능>\n14. 최근 3개월 동안 사용해본 기저귀의 브랜드와 세부 제품명을 모두 적어주세요.\nex) 하기스 매직컴포트 팬티 5단계, 팸퍼스 엔젤 에어차차 썸머팬티 5단계, 모모래빗 에코드라이 썸머 팬티 5단계, 페넬로페 씬씬씬 아이스 썸머팬티 5단계, 킨도 오슬림 에어팬티 5단계 등\n15. 현재 가장 자주 사용하는 기저귀 브랜드와 세부 제품명, 단계(크기)는 무엇인가요? <제품명 전체를 정확히 확인후 모두 적어주세요>\nex) 하기스 매직컴포트 팬티 5단계 등\n16. 기저귀 교체하는 상황을 촬영하는 것을 포함하여 모든 조사방식에 동의하시나요? <YES만 가능>\n17. 해당 일정 중 참여가능 시간을 모두 적어주세요.\nex) 11/5(목) 3타임 모",
