      "duration": "약 60분",
      "reward": "12만원 ( 조사 종료후 1주일내 계좌 지급, 기타소득세 신고 주민번호 수집 필수)",
      "location": "",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/30)만 35~39세 기혼여성) 전동칫솔 사용 가정 대상 홈비짓\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.19. 15:26\n조회 24\n구독\n10/30)만 35~49세 기혼여성) 전동칫솔 사용 가정 대상 홈비짓\n■ 대상자 조건\n· 만 35~49세 기혼 여성 (전업, 취업, 파트타이머 모두 가능)\n· 거주 지역: 서울 강남/서초/송파\n· 아파트에 거주하시는 분\n· 유치원~초등학교 저학년(1~3학년) 자녀를 키우고 계신 가정\n· 가구 소득 중상위 해당 가구 ( 맞벌이 합산 )\n· 가구 내 전동칫솔 또는 일반칫솔을 사용하고 계신 분\n· 낯선 사람과도 편하게 대화하며, 본인의 생활과 생각을 적극적으로 이야기해 주실 수 있는 분\n■ 진행 방식\n· 방식: 진행자 및 관계자 총 5명이 댁을 방문해 인터뷰 진행 ( 외국인 1명 포함)\n· 소요 시간: 약 60분\n· 내용: 전반적인 가정의 라이프 스타일을 살펴 보고자 함 ; 가족의 양치·구강 관리 습관 이야기, 욕실·세면대 등 칫솔 사용 공간 관찰등\n· 기록: 분석용 사진·영상 촬영 (외부 공개 없음, 연구 목적 외 사용하지 않음)\n■ 방문 일자\n· 일정: 10월 30일 금요일 오전 9시~11시중 조율가능\n■ 증빙 사진 요청 있음\n욕실 전체 사진 ( 여러 각도로 여러장)\n거실, 주방 사진 1장 씩 ( 가전, 인테리어 확인용)\n칫솔 거치된 사진 여러장\n■ 사례비\n12만원 ( 조사 종료후 1주일내 계좌 지급, 기타소득세 신고 주민번호 수집 필수)\n■ 신청 방법\n성명/연락처/성별/만나이/거주지 (동까지)/직업/가구 구성 ( 자녀 성별, 만나이 모두) / 조사 가능 시간 대 (모두)\n현재 사용중인 전동칫솔 브랜드+ 모델명, 구입년월, 구입가격, 가족중 사용자 모두 기입\nhttps://forms.gle/ML8qPm3kS5yGDvUj9\n10/30)만 35~49세 기혼여성) 전동칫솔 사용 가정 대상 홈비짓\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/30)만 40~49세 기혼여성) 전동칫솔 사용 가정 대상 홈비짓\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n10/30)만 35~39세 기혼여성) 전동칫솔 사용 가정 대상 홈비짓\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n11/5~7) 만 20~55세 여성)과학 방송 프로그램 관련 조사\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n11/5~7) 만 20~55세 남성)과학 방송 프로그램 관련 조사\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
