      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10~11월 중) 네트워크 마케팅 활동자 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.19. 23:03\n조회 36\n구독\n10~11월 중) 네트워크 마케팅 활동자 좌담회\n한국노동연구원에서 진행하는 네트워크 마케팅 활동자 좌담회에 참석하실 분들을 신청받고자 공지드립니다.\n이번 조사는 네트워크 마케팅 판매원의 활동 및 소득 구조와 고용보험 적용 시 예상되는 어려움 등에 대한 의견을 듣고, 제도 개선을 위한 기초자료를 마련하고자 진행합니다.\n총 모집 인원은 6명이며, 성별과 연령에는 제한이 없습니다.\n실제 판매·사업 활동 내용과 후원수당 수령 여부 등을 확인해야 하므로, 소개해주신 분들과 저희가 직접 통화한 후 최종 참석자를 선정할 예정입니다.\n〈기본 정보〉\n좌담회명: 네트워크 마케팅 활동자의 소득 및 사회보험 관련 FGI\n필수 조건: 현재 다단계 판매업체에 판매원으로 등록하여 판매 또는 사업 활동을 하고 계신 분 (후원수당 수령 여부와 관계없이 신청 가능)\n모집 인원: 6명\n일정: 10~11월 중, 참석자와 협의 후 확정\n장소: 서울 지역 내 회의실\n사례비: 20만원\n소요시간: 2시간 내외\n〈기본 질문〉\n성명 / 성별 / 연령 / 직업 / 휴대폰 번호 / 거주지역\n〈추가 질문〉\n현재 활동 중인 네트워크 마케팅 업체명은 무엇입니까?\n현재 어떤 활동을 하고 계십니까? (복수응답 가능) : 제품 판매 / 신규 판매원 가입 안내·모집 / 판매원 교육·관리 / 본인 또는 가족이 사용할 제품 구매만 하고 있다 / 현재 활동을 중단했다 / 기타\n현재 후원수당을 받고 계십니까? : 현재 정기적 또는 비정기적으로 받고 있다 / 과거에는 받았으나 현재는 받지 않는다 / 받은 적이 없다 / 후원수당인지 잘 모르겠다\n네트워크 마케팅 활동을 하신 기간은 얼마나 되십니까?\n최근 3개월 동안 해당 활동을 통해 얻은 월평균 수입은 어느 정도입니까?\nhttps://forms.gle/nqLkMXMTEEMozSf7A\n10~11월 중) 네트워크 마케팅 활동자 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/28~29)만 20세 이상~ 여성) 현재 취미로 발레 수업 (발레 학원,등)받은분_인터뷰 및 사용성 평가\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n10월20일~11월 중순) 럭셔리 브랜드(명품)관련 조사-만18~60세 여성\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n10~11월 중) 네트워크 마케팅 활동자 좌담회\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n10~11월 중) 학원강사 좌담회\n좌담회알바좌담회카페\n26.10.19.\n댓글\n0\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
