      "raw_content": "전동칫솔 사용 가정 홈비짓-서울 강남·서초·송파 만35~49세 기혼 여성 10/30[12만원]\n​\n대상 : 만35~49세 기혼 여성(전업, 취업, 파트타이머 모두 가능)\n서울 강남, 서초, 송파 거주자\n아파트 거주 가정\n유치원~초등학교 저학년(1~3학년) 자녀를 키우는 가정\n가구 소득 중상위 해당 가구(맞벌이 합산)\n가구 내 전동칫솔 또는 일반칫솔 사용자\n낯선 사람과도 편하게 대화하며 생활과 생각을 적극적으로 이야기할 수 있는 분\n일정 : 10/30(금) 오전 9시~11시 중 조율 가능\n방법 : 홈비짓(진행자 및 관계자 총 5명 방문, 외국인 1명 포함)\n가정의 라이프스타일, 가족의 양치·구강 관리 습관 인터뷰\n욕실·세면대 등 칫솔 사용 공간 관찰\n소요시간 : 약 1시간\n사례비 : 120,000원　조사 종료 후 1주일 이내 계좌 지급\n장소 : 본인 자택\n안내사항\n◆ 분석용 사진·영상 촬영 (외부 공개 없음, 연구 목적 외 사용하지 않음)\n◆ 기타소득세 신고를 위한 주민번호 수집 필수\n◆ 증빙 사진 요청\n1. 욕실 전체 사진 (여러 각도로 여러장)\n2. 거실, 주방 사진 1장 씩 (가전, 인테리어 확인용)\n3. 칫솔 거치된 사진 여러장\n​\n신청하기",
